package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.Minecraft;import net.minecraft.world.phys.Vec3;import net.minecraft.network.chat.Component;import java.util.*;
@net.neoforged.fml.common.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID,value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class NtClient {
 public static final Map<UUID,NtTunnel> TUNNELS=new LinkedHashMap<>();public static final List<Vec3> points=new ArrayList<>();private static final Deque<List<Vec3>> HISTORY=new ArrayDeque<>();
 public static NtGeometry.Settings settings=NtGeometry.Settings.defaults();public static NtGeometry.Plan preview;public static UUID editing;public static long revision;public static int sequence,selected=-1;public static boolean drawing=true,moving,pending;public static String status="Right-click the ground to add a route point.";private static Object world;private static int dirtyAt=-1,clock;
 private static void history(){HISTORY.addLast(List.copyOf(points));if(HISTORY.size()>64)HISTORY.removeFirst();}
 public static void changed(){sequence++;preview=null;pending=points.size()>0;dirtyAt=clock+2;NtRender.clearPreview();}
 public static void point(Vec3 p){var m=Minecraft.getInstance();if(m.player==null)return;if(!drawing&&!moving){open();return;}if(moving&&selected>=0&&selected<points.size()){history();points.set(selected,p);moving=false;status="Route point moved.";changed();return;}for(int i=0;i<points.size();i++)if(points.get(i).distanceToSqr(p)<.6*.6){selected=i;status="Point "+(i+1)+" selected. Open settings to move/delete it.";return;}if(points.size()>=64){status="Maximum 64 route points.";return;}history();points.add(p);selected=points.size()-1;status="Point "+points.size()+" added. Right-click air or sneak-use for settings.";changed();}
 public static void undoPoint(){if(HISTORY.isEmpty())return;points.clear();points.addAll(HISTORY.removeLast());selected=points.size()-1;changed();}
 public static void deletePoint(){if(selected<0||selected>=points.size())return;history();points.remove(selected);selected=Math.min(selected,points.size()-1);changed();}
 public static void cancel(){points.clear();HISTORY.clear();preview=null;editing=null;revision=0;selected=-1;drawing=true;moving=pending=false;sequence++;dirtyAt=-1;status="Route cancelled. Existing tunnels were not removed.";NtRender.clearPreview();}
 public static void load(NtTunnel t){cancel();editing=t.id();revision=t.revision();points.addAll(t.plan().points());settings=t.plan().settings();selected=points.size()-1;drawing=false;changed();status="Editing tunnel "+t.id().toString().substring(0,8)+" revision "+revision;}
 public static void open(){Minecraft.getInstance().setScreen(new NtScreen());}
 public static void send(int action){if(action==NtRequest.BUILD&&(pending||preview==null||!preview.valid()))return;AddonNetwork.ntRequest(new NtRequest(action,sequence,editing,revision,List.copyOf(points),settings,preview==null?"":preview.fingerprint()));pending=true;}
 private static void world(){var m=Minecraft.getInstance();if(world!=m.level){world=m.level;TUNNELS.clear();cancel();NtRender.clear();}}
 public static void receive(NtReply m){world();var mc=Minecraft.getInstance();if(mc.level==null||!mc.level.dimension().location().toString().equals(m.dimension()))return;if(m.kind()==NtReply.UPSERT){TUNNELS.put(m.id(),m.tunnel());NtRender.update(m.tunnel());return;}if(m.kind()==NtReply.REMOVE){TUNNELS.remove(m.id());NtRender.remove(m.id());return;}if(m.sequence()!=sequence)return;status=m.message();pending=false;if(m.kind()==NtReply.RESULT&&m.message().startsWith("Please wait")){pending=true;dirtyAt=clock+10;return;}if(m.kind()==NtReply.RESULT&&(m.message().startsWith("Tunnel removed")||m.message().startsWith("Last build undone"))){String text=m.message();cancel();status=text;return;}if(m.kind()==NtReply.PREVIEW){preview=m.tunnel()==null?null:m.tunnel().plan();NtRender.preview(m.tunnel());}else if(m.tunnel()!=null){editing=m.tunnel().id();revision=m.tunnel().revision();TUNNELS.put(editing,m.tunnel());NtRender.update(m.tunnel());preview=null;NtRender.clearPreview();drawing=false;}}
 @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){var m=Minecraft.getInstance();world();clock++;if(dirtyAt>=0&&clock>=dirtyAt&&m.player!=null&&m.player.getMainHandItem().is(AddonItems.NT01_BUILDER.get())){dirtyAt=-1;AddonNetwork.ntRequest(new NtRequest(NtRequest.PREVIEW,sequence,editing,revision,List.copyOf(points),settings,""));}if(m.player==null)NtRender.clear();}
 @net.neoforged.bus.api.SubscribeEvent public static void hud(net.neoforged.neoforge.client.event.RenderGuiEvent.Post e){var m=Minecraft.getInstance();if(m.player==null||m.screen!=null||m.options.hideGui||!m.player.getMainHandItem().is(AddonItems.NT01_BUILDER.get()))return;var g=e.getGuiGraphics();String help=moving?"NT-01: right-click new ground position": "NT-01 | "+points.size()+" points | sneak-use / use air: settings";g.drawString(m.font,help,8,8,0xffeeeeee,true);g.drawString(m.font,m.font.plainSubstrByWidth(status,g.guiWidth()-16),8,20,preview!=null&&!preview.valid()?0xffff7777:0xffccddcc,true);}
}
